const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={waiting_agent:'准备接续',agent_starting:'连接主 agent',agent_running:'主 agent 正在工作',agent_waiting:'本轮运行已结束',agent_failed:'本轮运行未完成',needs_input:'有事项需要你的判断',input_received:'指令已收到',tool_running:'工具正在计算',paused:'已暂停',cancelled:'已取消',source_changed:'新资料已到，可以建立下一版',succeeded:'已产出结果',failed:'未完成',superseded:'已被新输入替代',running:'计算中',received:'已收到',acknowledged:'已读取',auto_matched:'自动匹配',provisional:'暂定判断',needs_input_item:'请你判断',observation:'来源观察',calibrated:'倒算校准',management_guidance:'管理层指引',agent_assumption:'分析假设',accepted_for_run:'已授权本次采用',rejected:'未采用',proposed:'请你决定',open:'待回复',answered:'回复已收到'};
