const roleCopy={memo_librarian:{title:'Memo 知识管理员',rooms:['memo-library'],purpose:'整理已提交的 PFM memo、联席保荐人意见和监管问询回复，保留原文与对应版本关系。',goal:'阅读本次已选择的 PFM memo、联席保荐人意见及监管问询回复，核对每轮文件日期、对应版本、问题和处理结论；整理有出处的候选知识及关联版本说明。保留原文，采用、提交和发布由操作人决定。'},accounting_librarian:{title:'会计知识管理员',rooms:['accounting-library'],purpose:'按具体会计问题检索知识、配平案例和来源，整理可供审阅的处理依据。',goal:'围绕本次会计与配平问题检索已登记知识和案例，核对原始来源、适用条件、会计处理及勾稽关系；整理有出处的候选处理意见和需要补充的证据。知识整理与项目会计结论分别记录，采用和发布由操作人决定。'},audit_reviewer:{title:'项目审阅员',rooms:['audit-lab'],purpose:'审阅本项目的 PFM、memo 与支持资料，核对模型接线、数字假设及披露一致性，记录有出处的问题和复核结果。',goal:'审阅本项目的 PFM、memo、管理层讨论、FDD 和其他已选资料；核对模型接线和勾稽、数字与假设、memo 与模型一致性及相关监管问题。按具体来源、位置、影响和所需修改保存审阅发现，复核修订后更新状态；本任务形成审阅意见，不采用或改写模型。'},source_librarian:{title:'资料管理员',rooms:['intake','data-room'],purpose:'接收资料，识别用途、主体和期间，核对文件之间的关系，整理有出处的标准数据。',goal:'逐份阅读本次收件，核对提取结果并按业务用途分类；从原文识别资料日期、主体和覆盖期间。解释互补、并存、更新或替代关系，保留原文出处及待裁决问题；保存本职责工作间的资料目录、版本关系建议和来源支持的标准数据看板。'},precedent_librarian:{title:'先例图书管理员',rooms:['precedents'],purpose:'按建模需求检索有出处的模板和先例，整理适用条件、差异及审阅建议。',goal:'根据本次需求检索固定版本的模板与先例，核对来源、适用条件、输入输出和与需求的差异；形成有出处的候选目录与审阅建议。采用和发布另经授权，候选记录不自动进入模型或共享库。'}};
roleCopy.intake_librarian={...roleCopy.source_librarian,title:'收件资料管理员',rooms:['intake']};
