 async function refresh(g=generation){if(!slot||refreshing.has(g))return;refreshing.add(g);try{const id=selected.get(sessionKey());const data=id?await api(`/api/harness/${id}`):null;if(g!==generation)return;const value=requireRole(data?.run||null);const next=workspaceRenderKey(value);if(next!==renderKey){remember();run=value;last=next;if(run&&(chatOnly||reporting)&&slot.querySelector('[data-live-chat]')?.dataset.runId===run.id){patchRuntime();renderKey=next;announceRun();}else render();}else {run=value;patchRuntime();}}catch(e){if(g===generation)onError(e);}finally{refreshing.delete(g);if(g===generation)timer=setTimeout(()=>refresh(g),document.visibilityState==='hidden'?4000:run?.live_message||['starting','running'].includes(run?.agent_state?.status)?450:1400);}}
